/**
 * Modal side sheet (`design/components/drawer.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/drawer.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/dialog'
import { normalizeProps } from '@zag-js/solid'

import {
  ResolvedSlot,
  afresh,
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  mergeParts,
  modalFocusTarget,
  scope,
  useDirection,
  useMachine,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/drawer.module.css'
import Button from '../controls/Button'

export type DrawerSide = NonNullable<DrawerProps['side']>

export interface DrawerProps {
  children?: JSX.Element
  /**
   * The ✕'s accessible name, as in Dialog; localized hosts replace the default `Close`.
   */
  closeLabel?: string
  defaultOpen?: boolean
  description?: string
  /**
   * `false` removes ✕ and ignores Escape and outside clicks, forcing a choice.
   */
  dismissible?: boolean
  /**
   * Actions. One primary (`solid`), rightmost; dismiss is outline or ghost.
   */
  footer?: JSX.Element
  /**
   * The same as Dialog's, from the shared focus code: unset focuses the first tabbable per the
   * focus-order rule, and `dismiss` suits a panel asking whether you meant it.
   */
  initialFocus?: 'primary' | 'dismiss'
  onOpenChange?: (open: boolean) => void
  open?: boolean
  side?: 'start' | 'end' | 'bottom'
  /**
   * Inline size for a start/end sheet, block size for a bottom one. Both derive from the space
   * scale, so a roomier theme gets a larger sheet.
   */
  size?: 'sm' | 'md' | 'lg'
  title: string
}

/** Modal side sheet. */
export default function Drawer(given: DrawerProps): JSX.Element {
  const props = mergeProps(
    {
      side: 'end',
      size: 'md',
      dismissible: true,
      initialFocus: 'primary',
      closeLabel: 'Close',
    } as Defaults<DrawerProps, 'side' | 'size' | 'dismissible' | 'initialFocus' | 'closeLabel'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open,
          defaultOpen: props.defaultOpen,
          closeOnEscape: props.dismissible,
          closeOnInteractOutside: props.dismissible,
          initialFocusEl: () => modalFocusTarget(panel.value, props.initialFocus),
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const scrimPresent = usePresence(
      () => api.value.open,
      () => scrim.value,
      'dialog.scrim',
    )
    const panelPresent = usePresence(
      () => api.value.open,
      () => panel.value,
      'drawer.panel',
      {
        get sheetSide() {
          return props.side
        },
      },
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'Drawer',
        element: () => panel.value,
        state: () => ({ open: api.value.open }),
        actions: {
          close: () =>
            (() => {
              if (!props.dismissible)
                throw new Error('The drawer asks for a choice among its own actions.')
              if (api.value.open) api.value.setOpen(false)
            })(),
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <Portal>
        {afresh(() => (
          <>
            {scrimPresent() ? (
              <div
                {...mergeParts(api.value.getBackdropProps(), {
                  class: styles.scrim,
                  hidden: undefined,
                })}
                ref={scrim.attach}
              />
            ) : null}
            {panelPresent() ? (
              <ResolvedSlot of={() => props.footer}>
                {(footerSlot) => (
                  <div
                    {...mergeParts(api.value.getPositionerProps(), {
                      class: styles.positioner,
                      'data-side': props.side,
                    })}
                  >
                    {/* panel */}
                    <div
                      {...mergeParts(api.value.getContentProps(), {
                        class: styles.panel,
                        hidden: undefined,
                        'data-side': props.side,
                        'data-size': props.size,
                        'data-member': 'drawer',
                      })}
                      ref={panel.attach}
                    >
                      {/* header */}
                      <div class={styles.header}>
                        {/* heading */}
                        <div class={styles.heading}>
                          {/* title */}
                          <h2 {...mergeParts(api.value.getTitleProps(), { class: styles.title })}>
                            {props.title}
                          </h2>
                          {props.description !== undefined ? (
                            <p
                              {...mergeParts(api.value.getDescriptionProps(), {
                                class: styles.description,
                              })}
                            >
                              {props.description}
                            </p>
                          ) : null}
                        </div>
                        {props.dismissible ? (
                          <div class={styles.close} data-dialog-part="close">
                            <Button
                              variant="ghost"
                              tone="neutral"
                              size="sm"
                              iconOnly={true}
                              icon="close"
                              label={props.closeLabel}
                              onClick={() => api.value.setOpen(false)}
                            />
                          </div>
                        ) : null}
                      </div>
                      {/* body */}
                      <div class={styles.body} data-dialog-part="body">
                        {props.children}
                      </div>
                      {footerSlot.filled() ? (
                        <div class={styles.footer} data-dialog-part="footer">
                          {footerSlot()}
                        </div>
                      ) : null}
                    </div>
                  </div>
                )}
              </ResolvedSlot>
            ) : null}
          </>
        ))}
      </Portal>
    )
  })
}
